waves.point_eqs_eel:
i=cos(q2*.01*q4);
ii=sin(q2*.01*q4);
y=sample*i+.5;
x=sample*(ii)+.5;

ul=.003*bass_att*q4;
ll=.002*treb_att*q4;
r=(treb_att*.052+value1)*(above(sample,ll)*below(sample,ul));
g=(mid_att*.02+value2)*(above(sample,ll)*below(sample,ul));
b=(bass_att*.057+value2)*(above(sample,ll)*below(sample,ul));

preset.init_eqs_eel:
beatrate=5;
avgbeatrate=1;
bbtime=1;
lbbtime=.5;
avgdb=.5;
vol=1;
avgvol=.2;

preset.frame_eqs_eel:
db=(bass-lbass)*fps;
lbass=bass;
avgdb=avgdb*.99+abs(db)*.01;

//beatdection
rawbeatb=above(db,avgdb*2);
beatb=rawbeatb*above(time-lbbtime,.75*avgbeatrate)*above(bass_att,.3);

//beatrate calc
bbtime=time*beatb;
beatrate=beatb*(bbtime-lbbtime)+(1-beatb)*beatrate;
avgbeatrate=beatb*(avgbeatrate*.999+beatrate*.001)+(1-beatb)*avgbeatrate;
lbbtime=time*beatb+(1-beatb)*lbbtime;

bc=bc+beatb;



vol=(rawbeatb*(db-(avgdb))*.01);
avgvol=avgvol*.99+vol*.05;

mtime=mtime+min(avgvol*.5,.25);
q2=mtime;
q1=beatb;
q3=db;
q4=60/avgbeatrate;
q5=equal(bc%4,0)*beatb;

zoom=1;
decay=.99;
warp=0;
wrap=1;

ob_r=sin(q2*.01+bass*.01)*.5+.5;
ob_g=cos(q2*.001*q4+treb*.01)*.5+.5;
ob_b=sin(time*.001*q4)*.5+.5;
